def transform(grid):
    w = len(grid[0])
    c = next(j for j, v in enumerate(grid[0]) if v == 2)
    out = [[0] * w for _ in range(w)]
    edge = min(c, w - 1 - c)
    for r in range(w):
        for j in range(w):
            d = abs(j - c)
            if r <= edge and d == r:
                out[r][j] = 2
            elif r > edge and ((j - (r - edge) - edge) % 4 == 0):
                # From the edge-hit row onward, two diagonals continue inward.
                out[r][j] = 1
    return out

